def bn(channels):
    return nn.BatchNorm1d(channels, eps=1e-3, momentum=0.01)


class DeepSTARR(nn.Module):
    def __init__(self, length=249, filters=(256, 60, 60, 120), kernels=(7, 3, 5, 3), dense=(256, 256),
                 dropout=0.4, n_tasks=2):
        super().__init__()
        layers, c_in = [], 4
        for c_out, k in zip(filters, kernels):
            layers += [nn.Conv1d(c_in, c_out, k, padding="same"), bn(c_out), nn.ReLU(), nn.MaxPool1d(2)]
            c_in = c_out
            length //= 2
        self.body = nn.Sequential(*layers)
        head, f_in = [nn.Flatten()], c_in * length
        for f_out in dense:
            head += [nn.Linear(f_in, f_out), bn(f_out), nn.ReLU(), nn.Dropout(dropout)]
            f_in = f_out
        self.dense = nn.Sequential(*head)
        self.out = nn.Linear(f_in, n_tasks)          # the two one-unit heads, Dense_Dev and Dense_Hk

    def forward(self, x):
        return self.out(self.dense(self.body(x)))


def build_model():
    """Returns the network: (N, 4, 249) one-hot -> (N, 2) = [Dev, Hk]."""
    net = DeepSTARR()
    net.apply(keras_init)
    return net

