class DilatedResidual(nn.Module):
    def __init__(self, channels, dilation, k=3):
        super().__init__()
        self.conv = nn.Conv1d(channels, channels, k, padding=dilation * (k - 1) // 2, dilation=dilation)
        self.norm = bn(channels)

    def forward(self, x):
        return x + F.relu(self.norm(self.conv(x)))


