class DilatedResidualStack(nn.Module):
    def __init__(self, channels, dilations=(2, 4, 8), kernel=3):
        super().__init__()
        self.layers = nn.ModuleList()
        for d in dilations:
            self.layers.append(nn.Sequential(
                nn.Conv1d(channels, channels, kernel, padding=d * (kernel - 1) // 2, dilation=d),
                bn(channels),
                nn.ReLU(),
            ))

    def forward(self, x):
        for layer in self.layers:
            x = x + layer(x)
        return x


