class DilatedBlock(nn.Module):
    def __init__(self, ch, dilation, dropout=0.1):
        super().__init__()
        self.net = nn.Sequential(
            nn.BatchNorm1d(ch), nn.GELU(),
            nn.Conv1d(ch, ch, 3, padding=dilation, dilation=dilation),
            nn.BatchNorm1d(ch), nn.GELU(),
            nn.Conv1d(ch, ch, 1),
            nn.Dropout(dropout),
        )
        self.scale = nn.Parameter(torch.zeros(1))

    def forward(self, x):
        return x + self.scale * self.net(x)


class DilatedResNet(nn.Module):
    def __init__(self, ch=256, dilations=(1, 2, 4, 8, 16, 32), head_ch=128, dense=256, n_tasks=2):
        super().__init__()
        self.stem = nn.Sequential(
            nn.Conv1d(4, ch, 15, padding=7),
            nn.BatchNorm1d(ch), nn.GELU(),
            nn.MaxPool1d(2),  # 249 -> 124
        )
        self.blocks = nn.Sequential(*[DilatedBlock(ch, d) for d in dilations])
        self.reduce = nn.Sequential(
            nn.BatchNorm1d(ch), nn.GELU(),
            nn.MaxPool1d(4),  # 124 -> 31
            nn.Conv1d(ch, head_ch, 1),
            nn.BatchNorm1d(head_ch), nn.GELU(),
        )
        self.head = nn.Sequential(
            nn.Flatten(),
            nn.Linear(head_ch * 31, dense), nn.BatchNorm1d(dense), nn.GELU(), nn.Dropout(0.3),
            nn.Linear(dense, n_tasks),
        )

    def forward(self, x):
        x = self.stem(x)
        x = self.blocks(x)
        x = self.reduce(x)
        return self.head(x)


def build_model():
    """Returns the network: (N, 4, 249) one-hot -> (N, 2) = [Dev, Hk]."""
    net = DilatedResNet()
    net.apply(init_weights)
    return net

