class LN1d(nn.Module):
    def __init__(self, d):
        super().__init__()
        self.ln = nn.LayerNorm(d)

    def forward(self, x):
        return self.ln(x.transpose(1, 2)).transpose(1, 2)


class ConvNeXtBlock(nn.Module):
    def __init__(self, d, k=15, drop_path=0.0, ls_init=0.1):
        super().__init__()
        self.dw = nn.Conv1d(d, d, k, padding=k // 2, groups=d)
        self.norm = nn.LayerNorm(d)
        self.pw1 = nn.Linear(d, 4 * d)
        self.pw2 = nn.Linear(4 * d, d)
        self.gamma = nn.Parameter(ls_init * torch.ones(d))
        self.drop_path = drop_path

    def forward(self, x):
        y = self.dw(x).transpose(1, 2)          # (N, L, d)
        y = self.norm(y)
        y = self.pw2(F.gelu(self.pw1(y)))
        y = (y * self.gamma).transpose(1, 2)     # (N, d, L)
        if self.training and self.drop_path > 0:
            keep = (torch.rand(x.shape[0], 1, 1, device=x.device) >= self.drop_path).to(y.dtype)
            y = y * keep / (1.0 - self.drop_path)
        return x + y


class ConvNeXt1D(nn.Module):
    def __init__(self, dims=(128, 192, 256), depths=(2, 3, 3), k=15, max_drop_path=0.1, dense=256,
                 head_dropout=0.3, n_tasks=2):
        super().__init__()
        self.stem = nn.Sequential(nn.Conv1d(4, dims[0], 15, padding=7), LN1d(dims[0]), nn.GELU())
        total = sum(depths)
        rates = [max_drop_path * i / max(total - 1, 1) for i in range(total)]
        stages, idx = [], 0
        for s, (d, n) in enumerate(zip(dims, depths)):
            layers = []
            if s > 0:
                layers += [LN1d(dims[s - 1]), nn.Conv1d(dims[s - 1], d, 2, stride=2)]   # 249->124->62
            for _ in range(n):
                layers.append(ConvNeXtBlock(d, k, rates[idx]))
                idx += 1
            stages.append(nn.Sequential(*layers))
        self.stages = nn.Sequential(*stages)
        d = dims[-1]
        self.norm = nn.LayerNorm(d)
        self.attn = nn.Linear(d, 1)
        self.head = nn.Sequential(
            nn.Linear(3 * d, dense), nn.GELU(), nn.Dropout(head_dropout),
            nn.Linear(dense, dense), nn.GELU(), nn.Dropout(head_dropout),
        )
        self.out = nn.Linear(dense, n_tasks)

    def forward(self, x):
        h = self.stages(self.stem(x))            # (N, d, 62)
        h = self.norm(h.transpose(1, 2))         # (N, 62, d)
        w = torch.softmax(self.attn(h).float(), dim=1).to(h.dtype)
        z = torch.cat([(w * h).sum(dim=1), h.mean(dim=1), h.max(dim=1).values], dim=1)
        return self.out(self.head(z))


def init_weights(m):
    if isinstance(m, (nn.Conv1d, nn.Linear)):
        nn.init.trunc_normal_(m.weight, std=0.02)
        if m.bias is not None:
            nn.init.zeros_(m.bias)


def build_model():
    """Returns the network: (N, 4, 249) one-hot -> (N, 2) = [Dev, Hk]."""
    net = ConvNeXt1D()
    net.apply(init_weights)
    nn.init.xavier_uniform_(net.out.weight)
    return net

def bn(channels):
    return nn.BatchNorm1d(channels, eps=1e-3, momentum=0.01)


class GatedBlock(nn.Module):
    def __init__(self, d, skip, dilation, k=3, dropout=0.1):
        super().__init__()
        self.norm = bn(d)
        self.conv = nn.Conv1d(d, 2 * d, k, padding=dilation * (k - 1) // 2, dilation=dilation)
        self.drop = nn.Dropout(dropout)
        self.res = nn.Conv1d(d, d, 1)
        self.skip = nn.Conv1d(d, skip, 1)

    def forward(self, x):
        h = self.conv(self.norm(x))
        a, b = h.chunk(2, dim=1)
        g = torch.tanh(a) * torch.sigmoid(b)
        g = self.drop(g)
        return x + self.res(g), self.skip(g)


class GatedDilatedNet(nn.Module):
    def __init__(self, d=128, skip=128, dilations=(1, 2, 4, 8, 16, 32), cycles=2, out_ch=256, dense=256,
                 dropout=0.3, n_tasks=2):
        super().__init__()
        self.stem = nn.Sequential(
            nn.Conv1d(4, d, 15, padding=7), bn(d), nn.GELU(),
            nn.Conv1d(d, d, 5, padding=2), bn(d), nn.GELU(),
            nn.MaxPool1d(2),                     # 249 -> 124
            nn.Dropout(0.1),
        )
        self.blocks = nn.ModuleList([GatedBlock(d, skip, dil) for _ in range(cycles) for dil in dilations])
        self.post = nn.Sequential(nn.GELU(), nn.Conv1d(skip, out_ch, 1), nn.GELU())
        self.norm = nn.LayerNorm(out_ch)
        self.attn = nn.Linear(out_ch, 1)
        self.head = nn.Sequential(
            nn.Linear(3 * out_ch, dense), nn.GELU(), nn.Dropout(dropout),
            nn.Linear(dense, dense), nn.GELU(), nn.Dropout(dropout),
        )
        self.out = nn.Linear(dense, n_tasks)
        self.scale = 1.0 / math.sqrt(len(self.blocks))

    def forward(self, x):
        h = self.stem(x)
        s = 0
        for blk in self.blocks:
            h, sk = blk(h)
            s = s + sk
        z = self.post(s * self.scale).transpose(1, 2)   # (N, L, C)
        z = self.norm(z)
        w = torch.softmax(self.attn(z).float(), dim=1).to(z.dtype)
        att = (w * z).sum(dim=1)
        mean = z.mean(dim=1)
        mx = z.max(dim=1).values
        return self.out(self.head(torch.cat([att, mean, mx], dim=1)))


