class Inception(nn.Module):
    def __init__(self, c_in, branch, kernels):
        super().__init__()
        self.branches = nn.ModuleList([
            nn.Sequential(nn.Conv1d(c_in, branch, k, padding=k // 2), bn(branch), nn.GELU())
            for k in kernels
        ])
        self.pool = nn.MaxPool1d(2)

    def forward(self, x):
        return self.pool(torch.cat([b(x) for b in self.branches], dim=1))


class InceptionNet(nn.Module):
    def __init__(self, length=249, dense=(256, 256), dropout=0.4, n_tasks=2):
        super().__init__()
        cfg = [(96, (5, 11, 19)), (64, (3, 7, 11)), (64, (3, 5, 9)), (64, (3, 5, 7))]
        layers, c_in = [], 4
        for branch, ks in cfg:
            layers.append(Inception(c_in, branch, ks))
            c_in = branch * len(ks)
            length //= 2
        self.body = nn.Sequential(*layers)
        head, f_in = [nn.Flatten()], c_in * length
        for f_out in dense:
            head += [nn.Linear(f_in, f_out), bn(f_out), nn.ReLU(), nn.Dropout(dropout)]
            f_in = f_out
        self.dense = nn.Sequential(*head)
        self.out = nn.Linear(f_in, n_tasks)

    def forward(self, x):
        return self.out(self.dense(self.body(x)))


