class GlobalFilter(nn.Module):
    """Learned per-channel filter applied in the frequency domain (linear conv via zero padding)."""
    def __init__(self, d, n_tok):
        super().__init__()
        self.n_fft = 2 * n_tok
        n_freq = self.n_fft // 2 + 1
        self.weight = nn.Parameter(torch.randn(n_freq, d, 2) * 0.02)

    def forward(self, x):                      # x: (N, T, d)
        dtype = x.dtype
        T = x.shape[1]
        X = torch.fft.rfft(x.float(), n=self.n_fft, dim=1)
        W = torch.view_as_complex(self.weight.float().contiguous())
        y = torch.fft.irfft(X * W[None], n=self.n_fft, dim=1)[:, :T]
        return y.to(dtype)


class GFBlock(nn.Module):
    def __init__(self, d, n_tok, mlp_ratio=4, dropout=0.1):
        super().__init__()
        self.norm1 = nn.LayerNorm(d)
        self.filt = GlobalFilter(d, n_tok)
        self.norm2 = nn.LayerNorm(d)
        self.mlp = nn.Sequential(nn.Linear(d, mlp_ratio * d), nn.GELU(), nn.Dropout(dropout),
                                 nn.Linear(mlp_ratio * d, d))
        self.drop = nn.Dropout(dropout)

    def forward(self, x):
        y = self.filt(self.norm1(x))
        y = self.mlp(self.norm2(y))
        return x + self.drop(y)


class GFNet(nn.Module):
    def __init__(self, length=249, stem=128, d=192, n_layers=8, dense=256, dropout=0.3, n_tasks=2, max_shift=3):
        super().__init__()
