class DenseLayer(nn.Module):
    """BN-GELU-1x1 bottleneck, then BN-GELU-dilated k3 conv producing `growth` new channels."""
    def __init__(self, c_in, growth, dilation, bottleneck=4, dropout=0.1):
        super().__init__()
        mid = bottleneck * growth
        self.norm1 = bn(c_in)
        self.conv1 = nn.Conv1d(c_in, mid, 1)
        self.norm2 = bn(mid)
        self.conv2 = nn.Conv1d(mid, growth, 3, padding=dilation, dilation=dilation)
        self.drop = nn.Dropout(dropout)

    def forward(self, x):
        h = self.conv1(F.gelu(self.norm1(x)))
        h = self.conv2(F.gelu(self.norm2(h)))
        return torch.cat([x, self.drop(h)], dim=1)


