    def __init__(self, c_in, growth, dilations, dropout=0.1):
        super().__init__()
        layers, c = [], c_in
        for dil in dilations:
            layers.append(DenseLayer(c, growth, dil, dropout=dropout))
            c += growth
        self.layers = nn.Sequential(*layers)
        self.c_out = c

    def forward(self, x):
        return self.layers(x)


class DenseDilatedNet(nn.Module):
    def __init__(self, d=128, growth=48, dilations=(1, 2, 4, 8, 16, 32), out_ch=256, dense=256,
                 dropout=0.3, n_tasks=2, max_shift=3):
        super().__init__()
        self.max_shift = max_shift
        self.stem = nn.Sequential(
            nn.Conv1d(4, d, 15, padding=7), bn(d), nn.GELU(),
            nn.Conv1d(d, d, 5, padding=2), bn(d), nn.GELU(),
            nn.MaxPool1d(2),                     # 249 -> 124
            nn.Dropout(0.1),
        )
        self.block1 = DenseBlock(d, growth, dilations)
        c1 = self.block1.c_out
        c_t = c1 // 2
        self.trans = nn.Sequential(bn(c1), nn.GELU(), nn.Conv1d(c1, c_t, 1))
        self.block2 = DenseBlock(c_t, growth, dilations)
        c2 = self.block2.c_out
        self.post = nn.Sequential(bn(c2), nn.GELU(), nn.Conv1d(c2, out_ch, 1), nn.GELU())
        self.norm = nn.LayerNorm(out_ch)
        self.attn = nn.Linear(out_ch, 1)
        self.head = nn.Sequential(
            nn.Linear(3 * out_ch, dense), nn.GELU(), nn.Dropout(dropout),
            nn.Linear(dense, dense), nn.GELU(), nn.Dropout(dropout),
        )
        self.out = nn.Linear(dense, n_tasks)

    def forward(self, x):
        if self.training:
            x = random_shift(x, self.max_shift)
        h = self.stem(x)
        h = self.block1(h)
        h = self.trans(h)
        h = self.block2(h)
        z = self.post(h).transpose(1, 2)          # (N, L, C)
        z = self.norm(z)
        w = torch.softmax(self.attn(z).float(), dim=1).to(z.dtype)
        att = (w * z).sum(dim=1)
        mean = z.mean(dim=1)
        mx = z.max(dim=1).values
        return self.out(self.head(torch.cat([att, mean, mx], dim=1)))


