class PolyBlock(nn.Module):
    """Pi-net block: h <- h + W_o[(U gelu(dw(bn(h)))) * (V x0)], raising the polynomial degree in x0 by one."""
    def __init__(self, d, dilation, k=5, expand=2, dropout=0.1):
        super().__init__()
        self.norm = bn(d)
        self.dw = nn.Conv1d(d, d, k, padding=dilation * (k - 1) // 2, dilation=dilation, groups=d)
        self.u = nn.Conv1d(d, expand * d, 1)
        self.v = nn.Conv1d(d, expand * d, 1)
        self.out = nn.Conv1d(expand * d, d, 1)
        self.drop = nn.Dropout(dropout)

    def forward(self, h, x0):
        z = self.u(F.gelu(self.dw(self.norm(h))))
        y = z * self.v(x0)
        return h + self.drop(self.out(y))


class PiNet(nn.Module):
    def __init__(self, d=192, dilations=(1, 2, 4, 8, 16, 32), cycles=2, dense=256, dropout=0.3,
                 n_tasks=2, max_shift=3):
        super().__init__()
        self.max_shift = max_shift
        self.stem = nn.Sequential(
            nn.Conv1d(4, d, 15, padding=7), bn(d), nn.GELU(),
            nn.Conv1d(d, d, 5, padding=2), bn(d), nn.GELU(),
            nn.MaxPool1d(2),                     # 249 -> 124
            nn.Dropout(0.1),
        )
        self.x0_norm = bn(d)
        self.blocks = nn.ModuleList([PolyBlock(d, dil) for _ in range(cycles) for dil in dilations])
        self.norm = nn.LayerNorm(d)
        self.attn = nn.Linear(d, 1)
        self.head = nn.Sequential(
            nn.Linear(3 * d, dense), nn.GELU(), nn.Dropout(dropout),
            nn.Linear(dense, dense), nn.GELU(), nn.Dropout(dropout),
        )
        self.out = nn.Linear(dense, n_tasks)

    def forward(self, x):
        if self.training:
            x = random_shift(x, self.max_shift)
        h = self.stem(x)
        x0 = self.x0_norm(h)
        for blk in self.blocks:
            h = blk(h, x0)
        z = self.norm(h.transpose(1, 2))          # (N, L, C)
        w = torch.softmax(self.attn(z).float(), dim=1).to(z.dtype)
        att = (w * z).sum(dim=1)
        mean = z.mean(dim=1)
        mx = z.max(dim=1).values
        return self.out(self.head(torch.cat([att, mean, mx], dim=1)))


