class DilatedMixer(nn.Module):
    """Token mixing: depthwise dilated conv, GELU, pointwise projection."""
    def __init__(self, d, dilation, k=5):
        super().__init__()
        self.dw = nn.Conv1d(d, d, k, padding=dilation * (k - 1) // 2, dilation=dilation, groups=d)
        self.pw = nn.Linear(d, d)

    def forward(self, x):  # (B, T, d)
        z = self.dw(x.transpose(1, 2)).transpose(1, 2)
        return self.pw(F.gelu(z))


class NoisyTop2MoE(nn.Module):
    """Per-token mixture of expert FFNs with noisy top-k routing (dense compute, sparse gates)."""
    def __init__(self, d, hidden=512, n_experts=4, k=2, noise_std=0.5, dropout=0.1):
        super().__init__()
        self.E, self.k, self.noise_std = n_experts, k, noise_std
        self.router = nn.Linear(d, n_experts)
        s1 = math.sqrt(2.0 / (d + hidden))
        self.W1 = nn.Parameter(torch.randn(n_experts, d, hidden) * s1)
        self.b1 = nn.Parameter(torch.zeros(n_experts, hidden))
        self.W2 = nn.Parameter(torch.randn(n_experts, hidden, d) * s1)
        self.b2 = nn.Parameter(torch.zeros(n_experts, d))
        self.drop = nn.Dropout(dropout)

    def forward(self, x):  # (B, T, d)
        logits = self.router(x).float()
        if self.training and self.noise_std > 0:
            logits = logits + torch.randn_like(logits) * self.noise_std
        vals, idx = logits.topk(self.k, dim=-1)
        gates = torch.zeros_like(logits).scatter(-1, idx, torch.softmax(vals, dim=-1)).to(x.dtype)
        h = torch.einsum('btd,edh->bteh', x, self.W1) + self.b1
        h = self.drop(F.gelu(h))
        y = torch.einsum('bteh,ehd->bted', h, self.W2) + self.b2
        return (y * gates[..., None]).sum(dim=2)


class MoEBlock(nn.Module):
    def __init__(self, d, dilation, hidden=512, n_experts=4, dropout=0.1):
        super().__init__()
        self.norm1 = nn.LayerNorm(d)
        self.mix = DilatedMixer(d, dilation)
        self.norm2 = nn.LayerNorm(d)
        self.moe = NoisyTop2MoE(d, hidden, n_experts, dropout=dropout)
        self.drop = nn.Dropout(dropout)

    def forward(self, x):
        x = x + self.drop(self.mix(self.norm1(x)))
        x = x + self.drop(self.moe(self.norm2(x)))
        return x


