class RBFBasis(nn.Module):
    """Gaussian radial basis expansion: (..., C) -> (..., C, G)."""
    def __init__(self, G=8, lo=-2.0, hi=2.0):
        super().__init__()
        self.register_buffer("grid", torch.linspace(lo, hi, G))
        self.inv_h = (G - 1) / (hi - lo)

    def forward(self, x):
        return torch.exp(-((x[..., None] - self.grid) * self.inv_h) ** 2)


class FastKANLayer(nn.Module):
    """KAN layer: sum over inputs of learned RBF splines plus a SiLU base branch."""
    def __init__(self, d_in, d_out, G=8):
        super().__init__()
        self.rbf = RBFBasis(G)
        self.spline = nn.Linear(d_in * G, d_out, bias=False)
        self.base = nn.Linear(d_in, d_out)

    def forward(self, x):  # (B, L, d_in), roughly unit scale
        phi = self.rbf(x).flatten(-2)
        return self.spline(phi) + self.base(F.silu(x))


class KANDepthwiseConv(nn.Module):
    """Token mixing: per-channel dilated conv whose taps are learned spline functions of the input."""
    def __init__(self, C, k=7, dilation=1, G=8):
        super().__init__()
        self.G = G
        self.rbf = RBFBasis(G)
        pad = dilation * (k - 1) // 2
        self.spline = nn.Conv1d(C * G, C, k, dilation=dilation, padding=pad, groups=C, bias=False)
        self.base = nn.Conv1d(C, C, k, dilation=dilation, padding=pad, groups=C)

    def forward(self, x):  # (B, L, C)
        B, L, C = x.shape
        phi = self.rbf(x)                              # (B, L, C, G)
        phi = phi.permute(0, 2, 3, 1).reshape(B, C * self.G, L)
        y = self.spline(phi) + self.base(F.silu(x).transpose(1, 2))
        return y.transpose(1, 2)


class KANBlock(nn.Module):
    def __init__(self, d, dilation, G=8, k=7, mult=2, dropout=0.1):
        super().__init__()
        self.norm1 = nn.LayerNorm(d)
        self.tok = KANDepthwiseConv(d, k, dilation, G)
        self.norm2 = nn.LayerNorm(d)
        self.kan1 = FastKANLayer(d, mult * d, G)
        self.norm_mid = nn.LayerNorm(mult * d)
        self.kan2 = FastKANLayer(mult * d, d, G)
        self.drop = nn.Dropout(dropout)

    def forward(self, x):
        x = x + self.drop(self.tok(self.norm1(x)))
        y = self.kan2(self.norm_mid(self.kan1(self.norm2(x))))
        return x + self.drop(y)


class KANNet(nn.Module):
    def __init__(self, stem=256, d=128, dilations=(1, 2, 4, 8, 1, 2, 4, 8), G=8, k=7, dropout=0.1,
                 head_dropout=0.2, n_tasks=2, max_shift=3, checkpoint=True):
        super().__init__()
        self.max_shift = max_shift
        self.checkpoint = checkpoint
        self.stem = nn.Sequential(
            nn.Conv1d(4, stem, 15, padding=7),
            nn.BatchNorm1d(stem),
            nn.GELU(),
            nn.MaxPool1d(2),                      # 249 -> 124
            nn.Conv1d(stem, d, 1),
        )
        self.blocks = nn.ModuleList([KANBlock(d, dl, G, k, 2, dropout) for dl in dilations])
        self.norm = nn.LayerNorm(d)
        self.head = nn.Sequential(
            nn.Linear(2 * d, 256), nn.GELU(), nn.Dropout(head_dropout), nn.Linear(256, n_tasks)
        )

    def forward(self, x):
        if self.training:
            x = random_shift(x, self.max_shift)
        h = self.stem(x).transpose(1, 2)          # (B, 124, d)
        use_ckpt = self.checkpoint and self.training and torch.is_grad_enabled()
        for blk in self.blocks:
            if use_ckpt:
                h = _ckpt.checkpoint(blk, h, use_reentrant=False)
            else:
                h = blk(h)
        h = self.norm(h)
        pooled = torch.cat([h.mean(dim=1), h.max(dim=1).values], dim=-1)
        return self.head(pooled)


def build_model():
    """Returns the network: (N, 4, 249) one-hot -> (N, 2) = [Dev, Hk]."""
    net = KANNet()
    net.apply(init_weights)
    return net

