class RCConv(nn.Module):
    """Reverse-complement parameter-shared conv. Channels are laid out so that reversing
    the channel order gives the reverse complement (ACGT -> TGCA). Output has 2*c_half channels."""
    def __init__(self, c_in, c_half, k, dilation=1, padding=0, bias=True):
        super().__init__()
        self.dilation = dilation
        self.padding = padding
        self.weight = nn.Parameter(torch.empty(c_half, c_in, k))
        nn.init.kaiming_normal_(self.weight, nonlinearity="relu")
        self.bias = nn.Parameter(torch.zeros(c_half)) if bias else None

    def forward(self, x):
        w = torch.cat([self.weight, self.weight.flip([0, 1, 2])], dim=0)
        b = None
        if self.bias is not None:
            b = torch.cat([self.bias, self.bias.flip(0)], dim=0)
        return F.conv1d(x, w.to(x.dtype), None if b is None else b.to(x.dtype),
                        padding=self.padding, dilation=self.dilation)


class RCBatchNorm(nn.Module):
    """BatchNorm whose statistics and affine parameters are shared by each RC channel pair."""
    def __init__(self, c_half):
        super().__init__()
        self.c = c_half
        self.bn = nn.BatchNorm1d(c_half)

    def forward(self, x):
        n = x.shape[0]
        a = x[:, :self.c]
        b = x[:, self.c:].flip(1)
        y = self.bn(torch.cat([a, b], dim=0))
        a2, b2 = y[:n], y[n:]
        return torch.cat([a2, b2.flip(1)], dim=1)


class RCBlock(nn.Module):
    def __init__(self, c_half, dilation, dropout=0.1):
        super().__init__()
        self.n1 = RCBatchNorm(c_half)
        self.conv = RCConv(2 * c_half, c_half, 3, dilation=dilation, padding=dilation)
        self.n2 = RCBatchNorm(c_half)
        self.proj = RCConv(2 * c_half, c_half, 1)
        with torch.no_grad():
            self.proj.weight.mul_(0.5)
        self.drop = nn.Dropout(dropout)

    def forward(self, x):
        y = self.conv(F.gelu(self.n1(x)))
        y = self.proj(F.gelu(self.n2(y)))
        return x + self.drop(y)


class RCDilatedNet(nn.Module):
    def __init__(self, c_half=128, dilations=(1, 2, 4, 8, 16, 32, 1, 2, 4, 8, 16, 32), dropout=0.1,
                 head_dropout=0.2, n_tasks=2, max_shift=3, mask_p=0.03):
        super().__init__()
        self.c = c_half
        self.max_shift = max_shift
        self.mask_p = mask_p
        # k16, pad 7: 249 -> 248 (even, symmetric), so pooling by 2 stays RC-equivariant
        self.stem = RCConv(4, c_half, 16, padding=7)
        self.stem_norm = RCBatchNorm(c_half)
        self.pool = nn.MaxPool1d(2)
        self.blocks = nn.ModuleList([RCBlock(c_half, d, dropout) for d in dilations])
        self.final_norm = RCBatchNorm(c_half)
        self.ln = nn.LayerNorm(2 * c_half)
        self.head = nn.Sequential(
            nn.Linear(2 * c_half, 256), nn.GELU(), nn.Dropout(head_dropout), nn.Linear(256, n_tasks)
        )
        for m in self.head:
            if isinstance(m, nn.Linear):
                nn.init.xavier_uniform_(m.weight)
                nn.init.zeros_(m.bias)

    def forward(self, x):
        if self.training:
            x = random_shift(x, self.max_shift)
            x = random_position_mask(x, self.mask_p)
        h = self.pool(F.gelu(self.stem_norm(self.stem(x))))   # (N, 2C, 124)
        for blk in self.blocks:
            h = blk(h)
        h = F.gelu(self.final_norm(h))
        mean = h.mean(dim=-1)
        mx = h.max(dim=-1).values
        # sum the two strand halves -> reverse-complement invariant features
        mean = mean[:, :self.c] + mean[:, self.c:].flip(1)
        mx = mx[:, :self.c] + mx[:, self.c:].flip(1)
        z = self.ln(torch.cat([mean, mx], dim=-1).float())
        return self.head(z)


def build_model():
    """Returns the network: (N, 4, 249) one-hot -> (N, 2) = [Dev, Hk]."""
    return RCDilatedNet()

