def gaussian_input_noise(x, sigma):
    """Train-only: add N(0, sigma^2) noise to every input entry."""
    if sigma <= 0:
        return x
    return x + sigma * torch.randn_like(x)


def fo_pool(z, f):
    """QRNN forget-gate pooling: h_t = f_t * h_{t-1} + (1 - f_t) * z_t. z, f: (B, L, H) fp32."""
    L = z.shape[1]
    h = torch.zeros_like(z[:, 0])
    outs = []
    for t in range(L):
        ft = f[:, t]
        h = ft * h + (1.0 - ft) * z[:, t]
        outs.append(h)
    return torch.stack(outs, dim=1)


class QRNNMixer(nn.Module):
    """Bidirectional QRNN: conv-generated gates, data-dependent linear recurrence."""
    def __init__(self, d, h, k=3, dropout=0.1):
        super().__init__()
        self.h = h
        self.norm = nn.LayerNorm(d)
        self.proj = nn.Linear(d, 4 * h)
        self.dw = nn.Conv1d(4 * h, 4 * h, k, padding=k // 2, groups=4 * h)
        decay = torch.empty(2 * h).uniform_(0.3, 0.97)
        self.f_bias = nn.Parameter(torch.log(decay / (1.0 - decay)))
        self.out = nn.Linear(h, d)
        self.drop = nn.Dropout(dropout)

    def forward(self, x):  # x: (B, L, d)
        y = self.proj(self.norm(x))
        y = y + self.dw(y.transpose(1, 2)).transpose(1, 2)
        with torch.autocast(device_type=x.device.type, enabled=False):
            y = y.float()
            z, ff, fb, o = y.chunk(4, dim=-1)
            z = torch.tanh(z)
            bf, bb = self.f_bias.float().chunk(2)
            ff = torch.sigmoid(ff + bf)
            fb = torch.sigmoid(fb + bb)
            zz = torch.cat([z, torch.flip(z, dims=[1])], dim=-1)
            fa = torch.cat([ff, torch.flip(fb, dims=[1])], dim=-1)
            hs = fo_pool(zz, fa)
            hf, hb = hs.chunk(2, dim=-1)
            hb = torch.flip(hb, dims=[1])
            g = torch.sigmoid(o) * (hf + hb)
        return x + self.drop(self.out(g.to(x.dtype)))


class FFN(nn.Module):
    def __init__(self, d, mult=2, dropout=0.1):
        super().__init__()
        self.norm = nn.LayerNorm(d)
        self.fc1 = nn.Linear(d, mult * d)
        self.fc2 = nn.Linear(mult * d, d)
        self.drop = nn.Dropout(dropout)

    def forward(self, x):
        y = self.drop(F.gelu(self.fc1(self.norm(x))))
        return x + self.drop(self.fc2(y))


class QRNNBlock(nn.Module):
    def __init__(self, d, h, k=3, dropout=0.1):
        super().__init__()
        self.mix = QRNNMixer(d, h, k, dropout)
        self.ffn = FFN(d, 2, dropout)

    def forward(self, x):
        return self.ffn(self.mix(x))


class QRNNNet(nn.Module):
    def __init__(self, stem=128, d_model=256, h=384, n_layers=6, k=3, dropout=0.1, head_dropout=0.2, n_tasks=2, max_shift=3, mask_p=0.03, noise_sigma=0.15):
        super().__init__()
        self.max_shift = max_shift
        self.mask_p = mask_p
        self.noise_sigma = noise_sigma
        self.stem = nn.Sequential(
            nn.Conv1d(4, stem, 9, padding=4), bn(stem), nn.GELU(),
            nn.Conv1d(stem, stem, 9, padding=4), bn(stem), nn.GELU(),
            nn.MaxPool1d(2),                       # 249 -> 124
            nn.Dropout(0.1),
            nn.Conv1d(stem, d_model, 5, padding=2), bn(d_model), nn.GELU(),
            nn.MaxPool1d(2),                       # 124 -> 62
            nn.Dropout(0.1),
        )
        self.blocks = nn.ModuleList([QRNNBlock(d_model, h, k, dropout) for _ in range(n_layers)])
        self.norm = nn.LayerNorm(d_model)
        self.head = nn.Sequential(
            nn.Linear(2 * d_model, 256), nn.GELU(), nn.Dropout(head_dropout), nn.Linear(256, n_tasks)
        )

    def forward(self, x):
        if self.training:
            x = random_shift(x, self.max_shift)
            x = random_position_mask(x, self.mask_p)
            x = gaussian_input_noise(x, self.noise_sigma)
        h = self.stem(x).transpose(1, 2)  # (B, 62, d)
        for blk in self.blocks:
            h = blk(h)
        h = self.norm(h)
        pooled = torch.cat([h.mean(dim=1), h.max(dim=1).values], dim=-1)
        return self.head(pooled)


def build_model():
    """Returns the network: (N, 4, 249) one-hot -> (N, 2) = [Dev, Hk]."""
    net = QRNNNet()
    net.apply(init_weights)
    for blk in net.blocks:
        nn.init.zeros_(blk.mix.out.weight)
        nn.init.zeros_(blk.mix.out.bias)
        nn.init.zeros_(blk.ffn.fc2.weight)
        nn.init.zeros_(blk.ffn.fc2.bias)
    return net

def bn(channels):
    return nn.BatchNorm1d(channels, eps=1e-3, momentum=0.01)


def init_weights(m):
    if isinstance(m, (nn.Conv1d, nn.Linear)):
        nn.init.xavier_uniform_(m.weight)
        if m.bias is not None:
            nn.init.zeros_(m.bias)


def random_shift(x, max_shift):
    """Per-sample random shift in [-max_shift, max_shift] with zero padding."""
    if max_shift <= 0:
        return x
    n, c, L = x.shape
    xp = F.pad(x, (max_shift, max_shift))
    off = torch.randint(0, 2 * max_shift + 1, (n,), device=x.device)
    idx = torch.arange(L, device=x.device)[None, :] + off[:, None]
    idx = idx[:, None, :].expand(n, c, L)
    return xp.gather(2, idx)


def random_position_mask(x, p):
    """Train-only: set a random fraction p of positions to the uninformative 0.25 vector."""
    if p <= 0:
        return x
    n, c, L = x.shape
    m = torch.rand(n, 1, L, device=x.device) < p
    return torch.where(m, torch.full_like(x, 0.25), x)


def gaussian_input_noise(x, sigma):
    """Train-only: add N(0, sigma^2) noise to every input entry."""
    if sigma <= 0:
        return x
    return x + sigma * torch.randn_like(x)


class RPE(nn.Module):
    """Relative position encoder: maps a scalar offset to a per-channel kernel value."""
    def __init__(self, dim, hidden=64, n_layers=3):
        super().__init__()
        self.inp = nn.Linear(1, hidden)
        self.layers = nn.ModuleList([
            nn.Sequential(nn.LayerNorm(hidden), nn.ReLU(), nn.Linear(hidden, hidden)) for _ in range(n_layers)
        ])
        self.out = nn.Sequential(nn.LayerNorm(hidden), nn.ReLU(), nn.Linear(hidden, dim))

    def forward(self, pos):  # pos: (M, 1)
        h = self.inp(pos)
        for layer in self.layers:
            h = layer(h)
        return self.out(h)  # (M, dim)


class TNO(nn.Module):
    """Toeplitz neural operator: y_i = sum_j k(i-j) * gamma^|i-j| * v_j, per channel, in fp32."""
    def __init__(self, dim, gamma=0.99):
        super().__init__()
        self.rpe = RPE(dim)
        self.gamma = gamma

    def forward(self, v):  # v: (B, L, C) float32
        L = v.shape[1]
        dev = v.device
        n = torch.arange(-(L - 1), L, device=dev, dtype=torch.float32)
        k = self.rpe((n / L)[:, None])                      # (2L-1, C)
        k = k * (self.gamma ** n.abs())[:, None]
        i = torch.arange(L, device=dev)
        rel = i[:, None] - i[None, :] + (L - 1)             # (L, L)
        T = k[rel]                                          # (L, L, C)
        return torch.einsum('ijc,bjc->bic', T, v) / math.sqrt(L)


class GTU(nn.Module):
    """Gated Toeplitz unit: residual (LN -> silu(u) * TNO(silu(v)) -> out)."""
    def __init__(self, d, e, dropout=0.1):
        super().__init__()
        self.norm = nn.LayerNorm(d)
        self.u = nn.Linear(d, e)
        self.v = nn.Linear(d, e)
        self.tno = TNO(e)
        self.o = nn.Linear(e, d)
        self.drop = nn.Dropout(dropout)

    def forward(self, x):  # (B, L, d)
        h = self.norm(x)
        u = F.silu(self.u(h))
        v = F.silu(self.v(h))
        with torch.autocast(device_type=x.device.type, enabled=False):
            t = self.tno(v.float())
            g = u.float() * t
        return x + self.drop(self.o(g.to(x.dtype) if x.dtype != torch.float32 else g))


class GLUFFN(nn.Module):
    def __init__(self, d, ff, dropout=0.1):
        super().__init__()
        self.norm = nn.LayerNorm(d)
        self.fc1 = nn.Linear(d, 2 * ff)
        self.fc2 = nn.Linear(ff, d)
        self.drop = nn.Dropout(dropout)

    def forward(self, x):
        a, g = self.fc1(self.norm(x)).chunk(2, dim=-1)
        return x + self.drop(self.fc2(a * F.silu(g)))


class TNNLayer(nn.Module):
    def __init__(self, d, e, ff, dropout=0.1):
        super().__init__()
        self.gtu = GTU(d, e, dropout)
        self.ffn = GLUFFN(d, ff, dropout)

    def forward(self, x):
        return self.ffn(self.gtu(x))


class TNNNet(nn.Module):
    def __init__(self, stem=128, d_model=256, expand=512, ff=512, n_layers=6, dropout=0.1, head_dropout=0.2, n_tasks=2, max_shift=3, mask_p=0.03, noise_sigma=0.15):
        super().__init__()
        self.max_shift = max_shift
        self.mask_p = mask_p
        self.noise_sigma = noise_sigma
        self.stem = nn.Sequential(
            nn.Conv1d(4, stem, 9, padding=4), bn(stem), nn.GELU(),
            nn.Conv1d(stem, stem, 9, padding=4), bn(stem), nn.GELU(),
            nn.MaxPool1d(2),                       # 249 -> 124
            nn.Dropout(0.1),
            nn.Conv1d(stem, d_model, 5, padding=2), bn(d_model), nn.GELU(),
            nn.MaxPool1d(2),                       # 124 -> 62
            nn.Dropout(0.1),
        )
        self.blocks = nn.ModuleList([TNNLayer(d_model, expand, ff, dropout) for _ in range(n_layers)])
        self.norm = nn.LayerNorm(d_model)
        self.head = nn.Sequential(
            nn.Linear(2 * d_model, 256), nn.GELU(), nn.Dropout(head_dropout), nn.Linear(256, n_tasks)
        )

    def forward(self, x):
        if self.training:
            x = random_shift(x, self.max_shift)
            x = random_position_mask(x, self.mask_p)
            x = gaussian_input_noise(x, self.noise_sigma)
        h = self.stem(x).transpose(1, 2)  # (B, 62, d)
        for blk in self.blocks:
            h = blk(h)
        h = self.norm(h)
        pooled = torch.cat([h.mean(dim=1), h.max(dim=1).values], dim=-1)
        return self.head(pooled)


def build_model():
    """Returns the network: (N, 4, 249) one-hot -> (N, 2) = [Dev, Hk]."""
    net = TNNNet()
    net.apply(init_weights)
    for blk in net.blocks:
        nn.init.zeros_(blk.gtu.o.weight)
        nn.init.zeros_(blk.gtu.o.bias)
        nn.init.zeros_(blk.ffn.fc2.weight)
        nn.init.zeros_(blk.ffn.fc2.bias)
    return net
